pub const Tensor = struct {
    data: []u8,
    shape: []usize,
    strides: []usize,
    elem_size: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, shape: []const usize, comptime T: type) !Tensor {
        const elem_size = @sizeOf(T);
        var size: usize = 1;
        for (shape) |dim| size *= dim;
        const data = try allocator.alloc(u8, size * elem_size);
        @memset(data, 0);
        var strides = try allocator.alloc(usize, shape.len);
        var stride: usize = 1;
        var i = shape.len;
        while (i > 0) {
            i -= 1;
            strides[i] = stride;
            stride *= shape[i];
        }
        return .{
            .data = data,
            .shape = try allocator.dupe(usize, shape),
            .strides = strides,
            .elem_size = elem_size,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
    }

    fn linearIndex(self: *const Tensor, indices: []const usize) usize {
        var idx: usize = 0;
        var i: usize = 0;
        while (i < indices.len and i < self.strides.len) : (i += 1) {
            idx += indices[i] * self.strides[i];
        }
        return idx;
    }

    pub fn get(comptime T: type, self: *const Tensor, indices: []const usize) T {
        const idx = self.linearIndex(indices);
        const total_elems = self.data.len / self.elem_size;
        const bytes = self.data[0 .. total_elems * self.elem_size];
        const slice = std.mem.bytesAsSlice(T, bytes);
        return slice[idx];
    }

    pub fn set(comptime T: type, self: *Tensor, indices: []const usize, value: T) void {
        const idx = self.linearIndex(indices);
        const total_elems = self.data.len / self.elem_size;
        const bytes = self.data[0 .. total_elems * self.elem_size];
        const slice = std.mem.bytesAsSlice(T, bytes);
        slice[idx] = value;
    }
};

pub const ContextWindow = struct {
    tokens: []u32,
