            return error.WindowFull;
        }
    }

    pub fn clear(self: *ContextWindow) void {
        self.size = 0;
    }

    pub fn get(self: *const ContextWindow, index: usize) ?u32 {
        if (index >= self.size) return null;
        return self.tokens[index];
    }

