pub fn dotProduct(comptime T: type, a: []const T, b: []const T) !T {
    if (a.len != b.len) return error.ShapeMismatch;
    var result: T = 0;
    var i: usize = 0;
    while (i < a.len) : (i += 1) {
        result += a[i] * b[i];
    }
    return result;
}

