    return .{
        a[1] * b[2] - a[2] * b[1],
        a[2] * b[0] - a[0] * b[2],
        a[0] * b[1] - a[1] * b[0],
    };
}

pub fn norm(comptime T: type, vec: []const T) f32 {
    var sq_sum: f32 = 0.0;
    switch (@typeInfo(T)) {
        .Int => {
            for (vec) |val| {
                const f = @as(f32, @floatFromInt(val));
                sq_sum += f * f;
            }
        },
        .Float => {
            for (vec) |val| {
                const f = @as(f32, val);
                sq_sum += f * f;
            }
        },
        else => @compileError("norm not supported for type " ++ @typeName(T)),
    }
    return math.sqrt(sq_sum);
}

pub fn lerp(comptime T: type, a: T, b: T, t: f32) T {
    const fa = switch (@typeInfo(T)) {
        .Int => @as(f32, @floatFromInt(a)),
        .Float => @as(f32, a),
        else => @compileError("lerp not supported for type " ++ @typeName(T)),
    };
    const fb = switch (@typeInfo(T)) {
        .Int => @as(f32, @floatFromInt(b)),
        .Float => @as(f32, b),
        else => @compileError("lerp not supported for type " ++ @typeName(T)),
    };
    return switch (@typeInfo(T)) {
        .Int => @intFromFloat(fa + (fb - fa) * t),
        .Float => @as(T, fa + (fb - fa) * t),
        else => @compileError("lerp not supported for type " ++ @typeName(T)),
    };
}

pub fn factorial(n: usize) usize {
    if (n <= 1) return 1;
    var result: usize = 1;
    var i: usize = 2;
    while (i <= n) : (i += 1) {
        result *= i;
    }
    return result;
}

pub fn binomial(n: usize, k: usize) usize {
    if (k > n) return 0;
    if (k == 0 or k == n) return 1;
    const k_opt = if (k > n - k) n - k else k;
    var result: usize = 1;
    var i: usize = 0;
    while (i < k_opt) : (i += 1) {
        result *= (n - i);
        result /= (i + 1);
    }
    return result;
}

pub fn gcd(a: usize, b: usize) usize {
    var x = a;
    var y = b;
    while (y != 0) {
        const temp = y;
        y = x % y;
        x = temp;
    }
    return x;
}

pub fn lcm(a: usize, b: usize) usize {
    if (a == 0 or b == 0) return 0;
    return a / gcd(a, b) * b;
}

pub fn pow(comptime T: type, base: T, exp: usize) T {
    var result: T = 1;
    var e = exp;
    var b = base;
    while (e > 0) {
        if ((e & 1) == 1) result *= b;
        b *= b;
        e >>= 1;
    }
    return result;
}

